CREATE VIEW "TEST_AP"."B1_ItemPriceView" ( "ItemCode", "PriceList", "UomEntry", "Price", "Currency", "PriceType" ) AS ((SELECT T0."ItemCode", T0."PriceList", T0."UomEntry", T0."Price", T0."Currency", T0."PriceType" FROM  "TEST_AP"."ITM1" T0) UNION ALL (SELECT T0."ItemCode", T0."PriceList", T0."UomEntry", T0."Price", T0."Currency", T0."PriceType" FROM  "TEST_AP"."ITM9" T0)) WITH READ ONLY